<?php
namespace Tests\Feature;
use App\Models\{User,Owner,Venue,DesignAsset};use App\Services\VenueSettings;
use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\{Auth,Storage,Http};use Illuminate\Support\Str;use Tests\TestCase;
class LoginBrandingTest extends TestCase {
 use RefreshDatabase;
 private function venue():Venue {$u=User::factory()->create();$o=Owner::unguarded(fn()=>Owner::create(['user_id'=>$u->id,'name'=>'Dueño','email'=>$u->email,'password'=>'OwnerPassword12345','activated'=>true,'email_verified_at'=>now()]));return Venue::create(['owner_id'=>$u->id,'owner_account_id'=>$o->id,'name'=>'Local','slug'=>'local-'.Str::lower(Str::random(8)),'settings'=>VenueSettings::defaults(),'published'=>true]);}
 private function asset(Venue $v,string $kind='logo'):array {Storage::fake('local');return $this->actingAs($v->owner)->post('/api/owner/venues/'.$v->slug.'/design/assets',['kind'=>$kind,'image'=>UploadedFile::fake()->createWithContent('marca.png',base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aV1EAAAAASUVORK5CYII='))],['Accept'=>'application/json'])->assertCreated()->json();}
 private function guest():void {Auth::forgetGuards();config(['portal.kind'=>'client']);}
 public function test_repeated_successful_logins_do_not_exhaust_failure_limit():void {User::factory()->create(['email'=>'real@example.com','password'=>'CustomerPassword123']);for($i=0;$i<8;$i++){$this->postJson('/api/login',['email'=>'real@example.com','password'=>'CustomerPassword123'])->assertOk();$this->postJson('/api/logout')->assertOk();}}
 public function test_failure_limit_expires_and_has_retry_header():void {for($i=0;$i<5;$i++)$this->postJson('/api/login',['email'=>'bad@example.com','password'=>'wrong'])->assertUnprocessable();$r=$this->postJson('/api/login',['email'=>'bad@example.com','password'=>'wrong'])->assertStatus(429)->assertHeader('Retry-After');$this->assertGreaterThan(0,$r->json('retry_after'));$this->travel(61)->seconds();$this->postJson('/api/login',['email'=>'bad@example.com','password'=>'wrong'])->assertUnprocessable();}
 public function test_one_account_failure_does_not_block_another_account_or_owner_portal():void {for($i=0;$i<5;$i++)$this->postJson('/api/login',['email'=>'bad@example.com','password'=>'wrong'])->assertUnprocessable();User::factory()->create(['email'=>'another@example.com','password'=>'CustomerPassword123']);$this->postJson('/api/login',['email'=>'another@example.com','password'=>'CustomerPassword123'])->assertOk();$this->postJson('/api/logout')->assertOk();config(['portal.kind'=>'owner']);$this->postJson('/api/owner-auth/login',['email'=>'bad@example.com','password'=>'wrong'])->assertUnprocessable();}
 public function test_success_clears_previous_account_failures_and_email_case_is_supported():void {User::factory()->create(['email'=>'Mixed@Example.com','password'=>'CustomerPassword123']);for($i=0;$i<4;$i++)$this->postJson('/api/login',['email'=>'mixed@example.com','password'=>'wrong'])->assertUnprocessable();$this->postJson('/api/login',['email'=>'MIXED@example.com','password'=>'CustomerPassword123'])->assertOk();$this->postJson('/api/logout')->assertOk();for($i=0;$i<5;$i++)$this->postJson('/api/login',['email'=>'mixed@example.com','password'=>'wrong'])->assertUnprocessable();}
 public function test_invalid_email_shape_is_validation_error_not_server_error():void {$this->postJson('/api/login',['email'=>['unexpected'],'password'=>'wrong'])->assertUnprocessable();}
 public function test_registration_normalizes_email_and_rejects_case_duplicate():void {User::factory()->create(['email'=>'Mixed@Example.com']);$this->postJson('/api/register',['name'=>'Cliente','email'=>'MIXED@example.com','password'=>'CustomerPassword123','password_confirmation'=>'CustomerPassword123'])->assertUnprocessable();}
 public function test_legacy_accounts_with_case_only_difference_keep_exact_access():void {$a=User::factory()->create(['email'=>'Same@Example.com','password'=>'FirstPassword123']);$b=User::factory()->create(['email'=>'same@example.com','password'=>'SecondPassword123']);$this->postJson('/api/login',['email'=>'Same@Example.com','password'=>'FirstPassword123'])->assertOk()->assertJsonPath('user.id',$a->id);$this->postJson('/api/logout')->assertOk();$this->postJson('/api/login',['email'=>'same@example.com','password'=>'SecondPassword123'])->assertOk()->assertJsonPath('user.id',$b->id);}
 public function test_network_limit_also_blocks_distributed_account_attempts():void {for($i=0;$i<60;$i++)$this->postJson('/api/login',['email'=>"bad{$i}@example.com",'password'=>'wrong'])->assertUnprocessable();$this->postJson('/api/login',['email'=>'new@example.com','password'=>'wrong'])->assertStatus(429);}
 public function test_owner_successful_login_is_not_limited_as_a_failure():void {$v=$this->venue();config(['portal.kind'=>'owner']);for($i=0;$i<7;$i++){$this->postJson('/api/owner-auth/login',['email'=>$v->owner->email,'password'=>'OwnerPassword12345'])->assertOk();$this->postJson('/api/owner-auth/logout')->assertOk();}}
 public function test_owner_portal_cannot_call_customer_chat_or_consume_api():void {$v=$this->venue();Http::fake();$this->actingAs($v->owner)->postJson('/api/venues/'.$v->slug.'/chat',['message'=>'Precios','conversation'=>(string)Str::uuid()])->assertForbidden();Http::assertNothingSent();}
 public function test_disabled_public_chat_does_not_consume_ai():void {$v=$this->venue();$v->design=['show_chat'=>false];$v->save();Http::fake();$this->postJson('/api/venues/'.$v->slug.'/chat',['message'=>'Precios','conversation'=>(string)Str::uuid()])->assertStatus(423);Http::assertNothingSent();$this->assertDatabaseCount('chat_conversations',0);}
 public function test_logo_upload_is_private_until_published_and_draft_changes_preserve_public_logo():void {$v=$this->venue();$a=$this->asset($v);$this->assertArrayNotHasKey('path',$a);$this->get('/api/media/branding/'.$a['id'])->assertOk();$this->guest();$this->get('/api/media/branding/'.$a['id'])->assertNotFound();$d=app(\App\Http\Controllers\DesignController::class)->defaults();$d['logo_id']=$a['id'];$this->actingAs($v->owner)->putJson('/api/owner/venues/'.$v->slug.'/design',$d+['publish'=>true])->assertOk();$this->guest();$this->get('/api/media/branding/'.$a['id'])->assertOk();$d['logo_id']=null;$this->actingAs($v->owner)->putJson('/api/owner/venues/'.$v->slug.'/design',$d)->assertOk();$this->guest();$this->get('/api/media/branding/'.$a['id'])->assertOk();$v->update(['published'=>false]);$this->get('/api/media/branding/'.$a['id'])->assertNotFound();}
 public function test_logo_cannot_be_assigned_to_another_venue_or_as_favicon():void {$v=$this->venue();$a=$this->asset($v);$other=$this->venue();$d=app(\App\Http\Controllers\DesignController::class)->defaults();$d['logo_id']=$a['id'];$this->actingAs($other->owner)->putJson('/api/owner/venues/'.$other->slug.'/design',$d)->assertUnprocessable();$d['logo_id']=null;$d['favicon_id']=$a['id'];$this->actingAs($v->owner)->putJson('/api/owner/venues/'.$v->slug.'/design',$d)->assertUnprocessable();}
 public function test_upload_rejects_svg_and_cross_owner_writes():void {$v=$this->venue();$other=$this->venue();$this->actingAs($other->owner)->post('/api/owner/venues/'.$v->slug.'/design/assets',['kind'=>'logo','image'=>UploadedFile::fake()->createWithContent('logo.svg','<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script></svg>')],['Accept'=>'application/json'])->assertForbidden();$this->actingAs($v->owner)->post('/api/owner/venues/'.$v->slug.'/design/assets',['kind'=>'logo','image'=>UploadedFile::fake()->createWithContent('logo.svg','<svg xmlns="http://www.w3.org/2000/svg"/>')],['Accept'=>'application/json'])->assertUnprocessable();}
 public function test_used_asset_cannot_be_deleted_until_unlinked_and_unpublished():void {$v=$this->venue();$a=$this->asset($v);$d=app(\App\Http\Controllers\DesignController::class)->defaults();$d['logo_id']=$a['id'];$url='/api/owner/venues/'.$v->slug.'/design';$this->putJson($url,$d+['publish'=>true])->assertOk();$this->deleteJson($url.'/assets/'.$a['id'])->assertUnprocessable();$d['logo_id']=null;$this->putJson($url,$d)->assertOk();$this->deleteJson($url.'/assets/'.$a['id'])->assertUnprocessable();$this->putJson($url,$d+['publish'=>true])->assertOk();$path=DesignAsset::find($a['id'])->path;$this->deleteJson($url.'/assets/'.$a['id'])->assertOk();Storage::disk('local')->assertMissing($path);}
 public function test_new_design_options_publish_and_reject_external_font_or_asset_injection():void {$v=$this->venue();$d=array_replace(app(\App\Http\Controllers\DesignController::class)->defaults(),['font'=>'humanist','brand_name'=>'Mi marca','font_size'=>'large','show_map'=>false,'hero'=>'stacked']);$this->actingAs($v->owner)->putJson('/api/owner/venues/'.$v->slug.'/design',$d+['publish'=>true])->assertOk();$this->getJson('/api/venues/'.$v->slug)->assertJsonPath('design.brand_name','Mi marca')->assertJsonPath('design.font','humanist');$d['font']='url(https://evil.invalid/font)';$this->putJson('/api/owner/venues/'.$v->slug.'/design',$d)->assertUnprocessable();}
}
